package app.mambo.next;
import org.json.*;import java.net.*;import java.util.*;
/** Strict, credential-safe WireGuard import; never executes wg-quick hooks. */
public final class WireGuard {
 static Exception bad(String s){return new Exception("WireGuard: "+s);}
 static String key(String s)throws Exception{try{byte[] b=Base64.getDecoder().decode(s.trim().replace('-','+').replace('_','/'));if(b.length!=32)throw new Exception();return Base64.getEncoder().encodeToString(b);}catch(Exception e){throw bad("ключ должен содержать 32 байта Base64");}}
 static String ip(String s)throws Exception{if(!s.matches("[0-9a-fA-F:.]+")||(!s.contains(":")&&!s.matches("[0-9]+\\.[0-9]+\\.[0-9]+\\.[0-9]+")))throw bad("нужен IP-адрес");try{return InetAddress.getByName(s).getHostAddress();}catch(Exception e){throw bad("некорректный IP-адрес");}}
 static String network(String s)throws Exception{String[] a=s.trim().split("/",-1);if(a.length>2)throw bad("некорректный IP/CIDR");String h=ip(a[0]);int bits=h.contains(":")?128:32,n=bits;try{if(a.length==2)n=Integer.parseInt(a[1]);}catch(Exception e){throw bad("некорректная маска");}if(n<0||n>bits)throw bad("некорректная маска");return h+"/"+n;}
 static String addresses(String s)throws Exception{List<String> a=new ArrayList<>();for(String x:s.split("[,\\s]+"))if(!x.isEmpty())a.add(network(x));return String.join(",",a);}
 static int number(String s,int min,int max,String field)throws Exception{try{int v=Integer.parseInt(s);if(v<min||v>max)throw new Exception();return v;}catch(Exception e){throw bad("некорректный "+field);}}
 static JSONArray reserved(String s)throws Exception{try{JSONArray r=new JSONArray();s=s.trim();if(s.startsWith("[")&&s.endsWith("]"))s=s.substring(1,s.length()-1);if(s.contains(",")){for(String x:s.split(",",-1))r.put(number(x.trim(),0,255,"Reserved"));}else{for(byte b:Base64.getDecoder().decode(s.replace('-','+').replace('_','/')))r.put(b&255);}if(r.length()!=3)throw new Exception();return r;}catch(Exception e){throw bad("Reserved должен содержать 3 байта");}}
 static String dns(String s)throws Exception{List<String> out=new ArrayList<>();for(String x:s.split("[,\\s]+")){if(x.isEmpty())continue;out.add(ip(x));}return String.join(",",out);}
 static String field(String s){return s.toLowerCase(Locale.ROOT).replace("_","").replace("-","");}
 static String get(Map<String,String> m,String key,String def){return m.containsKey(key)?m.get(key):def;}
 static void put(Map<String,String> m,String k,String v)throws Exception{if(m.containsKey(k)){if(Arrays.asList("address","dns","allowedips").contains(k))v=m.get(k)+","+v;else throw bad("повторяющийся параметр");}m.put(k,v);}
 static void allowed(Map<String,String> m,String... keys)throws Exception{Set<String> ok=new HashSet<>(Arrays.asList(keys));for(String k:m.keySet())if(!ok.contains(k))throw bad("неподдерживаемый параметр; AmneziaWG и команды wg-quick не поддерживаются");}
 static JSONObject peer(Map<String,String> m)throws Exception{String endpoint=get(m,"endpoint","");URI ep;try{ep=new URI("udp://"+endpoint);if(ep.getRawUserInfo()!=null||ep.getRawQuery()!=null||ep.getRawFragment()!=null||!(ep.getRawPath()==null||ep.getRawPath().isEmpty()))throw new Exception();Profiles.host(ep);if(ep.getPort()<1)throw new Exception();Profiles.port(ep,51820);}catch(Exception e){throw bad("Endpoint должен содержать хост и порт; IPv6 — в квадратных скобках");}JSONObject p=Profiles.o("publicKey",key(get(m,"publickey","")),"endpoint",endpoint,"allowedIPs",Profiles.csv(addresses(get(m,"allowedips","0.0.0.0/0,::/0"))),"keepAlive",number(get(m,"persistentkeepalive",get(m,"keepalive","25")),0,65535,"KeepAlive"));if(m.containsKey("presharedkey"))p.put("preSharedKey",key(m.get("presharedkey")));return p;}
 static JSONObject build(String raw,String name,Map<String,String> iface,JSONArray peers)throws Exception{return Profiles.wg(raw,name,key(get(iface,"privatekey","")),addresses(get(iface,"address","")),peers,number(get(iface,"mtu","1420"),576,9000,"MTU"),iface.containsKey("reserved")?reserved(iface.get("reserved")):Profiles.a(0,0,0),dns(get(iface,"dns","")));}
 public static JSONObject conf(String raw)throws Exception{Map<String,String> iface=new HashMap<>(),section=null;List<Map<String,String>> peers=new ArrayList<>();boolean seen=false;for(String line:raw.replace("\ufeff","").split("\\r?\\n")){line=line.trim();if(line.isEmpty()||line.startsWith("#")||line.startsWith(";"))continue;if(line.equalsIgnoreCase("[Interface]")){if(seen)throw bad("несколько Interface");seen=true;section=iface;continue;}if(line.equalsIgnoreCase("[Peer]")){section=new HashMap<>();peers.add(section);continue;}String[] v=line.split("=",2);if(section==null||v.length!=2||line.startsWith("["))throw bad("некорректный .conf");put(section,field(v[0].trim()),v[1].split("\\s[#;]",2)[0].trim());}allowed(iface,"privatekey","address","dns","mtu","reserved","listenport","table","saveconfig");JSONArray ps=new JSONArray();for(Map<String,String> m:peers){allowed(m,"publickey","presharedkey","endpoint","allowedips","persistentkeepalive","reserved");if(m.containsKey("reserved")){if(iface.containsKey("reserved")&&!reserved(iface.get("reserved")).toString().equals(reserved(m.get("reserved")).toString()))throw bad("разный Reserved у пиров не поддерживается");iface.put("reserved",m.get("reserved"));}ps.put(peer(m));}return build(raw,"",iface,ps);}
 public static JSONObject uri(String raw)throws Exception{String rest=raw.substring(raw.indexOf("://")+3);int at=rest.indexOf('@');if(at<0)throw bad("в ссылке нужен приватный ключ перед @");String secret=Profiles.dec(rest.substring(0,at));URI u;try{u=new URI("wg://"+rest.substring(at+1));}catch(Exception e){throw bad("некорректная ссылка");}String h=Profiles.host(u);if(u.getRawPath()!=null&&!u.getRawPath().isEmpty()&&!u.getRawPath().equals("/"))throw bad("некорректный путь ссылки");Map<String,String> q=new HashMap<>();if(u.getRawQuery()!=null)for(String part:u.getRawQuery().split("&")){String[] v=part.split("=",2);String k=field(Profiles.dec(v[0]));if(k.equals("ip")||k.equals("localaddress"))k="address";if(k.equals("psk"))k="presharedkey";if(k.equals("publick")||k.equals("pubkey"))k="publickey";put(q,k,v.length==2?Profiles.dec(v[1]):"");}allowed(q,"address","publickey","presharedkey","allowedips","keepalive","persistentkeepalive","mtu","reserved","dns");q.put("privatekey",secret);q.put("endpoint",(h.contains(":")?"["+h+"]":h)+":"+Profiles.port(u,51820));String name=u.getRawFragment()==null?"":Profiles.dec(u.getRawFragment());return build(raw,name,q,Profiles.a(peer(q)));}
}
